class Program
{
    static void BFS(Dictionary<int, List<int>> graph, int start)
    {
        var visited = new HashSet<int>();
        var queue = new Queue<int>();
        visited.Add(start);
        queue.Enqueue(start);

        while (queue.Count > 0)
        {
            int node = queue.Dequeue();
            Console.Write(node + " ");
            foreach (int neighbor in graph[node])
            {
                if (!visited.Contains(neighbor))
                {
                    visited.Add(neighbor);
                    queue.Enqueue(neighbor);
                }
            }
        }
    }

    static void Main()
    {
        var graph = new Dictionary<int, List<int>>
        {
            { 0, new List<int> { 1, 2 } },
            { 1, new List<int> { 0, 3, 4 } },
            { 2, new List<int> { 0, 5 } },
            { 3, new List<int> { 1 } },
            { 4, new List<int> { 1 } },
            { 5, new List<int> { 2 } }
        };
        BFS(graph, 0);
    }
}

using System;

class Program
{
    // البحث الثنائي يفترض أن المصفوفة مرتبة تصاعدياً
    static int BinarySearch(int[] arr, int target)
    {
        int left = 0, right = arr.Length - 1;
        while (left <= right)
        {
            int mid = left + (right - left) / 2; // تجنب تجاوز الحد الأقصى
            if (arr[mid] == target)
                return mid;
            if (arr[mid] < target)
                left = mid + 1; // تجاهل النصف الأيسر
            else
                right = mid - 1; // تجاهل النصف الأيمن
        }
        return -1; // لم يوجد
    }

    static void Main()
    {
        int[] numbers = { 2, 5, 8, 12, 16, 23, 38, 56, 72, 91 };
        int target = 23;
        int index = BinarySearch(numbers, target);
        Console.WriteLine(index >= 0 ? "Found at index " + index : "Not found");
    }
}

using System;

class Node
{
    public int Data;
    public Node Left, Right;
    public Node(int d) { Data = d; Left = Right = null; }
}

class Program
{
    static void Main()
    {
        Node root = null;
        int[] values = { 50, 30, 70, 20, 40, 60, 80 };
        foreach (int v in values)
            root = Insert(root, v);

        InOrder(root);
    }

    static Node Insert(Node root, int key)
    {
        if (root == null) return new Node(key);
        if (key < root.Data)
            root.Left = Insert(root.Left, key);
        else if (key > root.Data)
            root.Right = Insert(root.Right, key);
        return root;
    }

    static void InOrder(Node root)
    {
        if (root == null) return;
        InOrder(root.Left);
        Console.Write(root.Data + " ");
        InOrder(root.Right);
    }
}

