using System;

class Program
{
    static long FactorialIterative(int n)
    {
        long result = 1;
        for (int i = 2; i <= n; i++)
            result *= i;
        return result;
    }

    static long FactorialRecursive(int n)
    {
        return n <= 1 ? 1 : n * FactorialRecursive(n - 1);
    }

    static void Main()
    {
        int[] numbers = { 5, 10, 15 };
        foreach (int n in numbers)
        {
            Console.WriteLine($"n={n}: iterative={FactorialIterative(n)}, recursive={FactorialRecursive(n)}");
        }
    }
}

