using System;

class Program
{
    static void InsertionSort(int[] arr)
    {
        for (int i = 1; i < arr.Length; i++)
        {
            int key = arr[i];
            int j = i - 1;
            // ننقل العناصر الأكبر من المفتاح إلى اليمين
            while (j >= 0 && arr[j] > key)
            {
                arr[j + 1] = arr[j];
                j--;
            }
            arr[j + 1] = key;
        }
    }

    static void Main()
    {
        int[] arr = { 5, 2, 4, 6, 1, 3 };
        InsertionSort(arr);
        Console.WriteLine(string.Join(" ", arr));
    }
}

