        int[,] A = { { 1, 2 }, { 3, 4 } };
        int[,] B = { { 5, 6 }, { 7, 8 } };
        int rowsA = A.GetLength(0), colsA = A.GetLength(1);
        int rowsB = B.GetLength(0), colsB = B.GetLength(1);

