class Program
{
    static Dictionary<int, long> cache = new Dictionary<int, long>();

    static long Fact(int n)
    {
        // إذا كانت النتيجة محفوظة نعيدها فورًا
        if (cache.ContainsKey(n)) return cache[n];
        // الحالة الأساسية
        if (n <= 1) return cache[n] = 1;
        // نحفظ النتيجة قبل إرجاعها
        return cache[n] = n * Fact(n - 1);
    }

    static void Main()
    {
        Console.WriteLine(Fact(10));
        Console.WriteLine(Fact(10)); // ستُحسب من الكاش
    }
}

