class Program
{
    static bool IsPerfect(int n)
    {
        int sum = 1; // 1 دائمًا قاسم
        for (int i = 2; i * i <= n; i++)
        {
            if (n % i == 0)
            {
                sum += i;
                if (i != n / i) sum += n / i; // تجنب تكرار الجذر التربيعي
            }
        }
        return n > 1 && sum == n;
    }

    static void Main()
    {
        Console.WriteLine("Perfect numbers up to 10000:");
        for (int i = 2; i <= 10000; i++)
        {
            if (IsPerfect(i))
                Console.WriteLine(i);
        }
    }
}

