using System;

class Program
{
    static void QuickSort(int[] arr, int low, int high)
    {
        if (low < high)
        {
            int pi = Partition(arr, low, high);
            QuickSort(arr, low, pi - 1);  // فرز الجزء الأيسر
            QuickSort(arr, pi + 1, high); // فرز الجزء الأيمن
        }
    }

    static int Partition(int[] arr, int low, int high)
    {
        int pivot = arr[high]; // اختيار آخر عنصر كمحور
        int i = low - 1;
        for (int j = low; j < high; j++)
        {
            if (arr[j] < pivot)
            {
                i++;
                Swap(arr, i, j); // نقل العناصر الأصغر للمحور لليسار
            }
        }
        Swap(arr, i + 1, high); // وضع المحور في مكانه الصحيح
        return i + 1;
    }

    static void Swap(int[] arr, int a, int b)
    {
        int temp = arr[a];
        arr[a] = arr[b];
        arr[b] = temp;
    }

    static void Main()
    {
        int[] arr = { 10, 7, 8, 9, 1, 5 };
        QuickSort(arr, 0, arr.Length - 1);
        Console.WriteLine(string.Join(" ", arr));
    }
}

