using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        string expr = "{[()]}";
        Console.WriteLine(IsBalanced(expr) ? "Balanced" : "Not Balanced");
    }

    static bool IsBalanced(string s)
    {
        Stack<char> stack = new Stack<char>();
        foreach (char c in s)
        {
            if (c == '(' || c == '[' || c == '{')
                stack.Push(c);
            else
            {
                if (stack.Count == 0) return false;
                char top = stack.Pop();
                if ((c == ')' && top != '(') ||
                    (c == ']' && top != '[') ||
                    (c == '}' && top != '{'))
                    return false;
            }
        }
        return stack.Count == 0;
    }
}

