class Program
{
    static void Main()
    {
        // عدد الأقراص في البرج
        int n = 3;

        // نستدعي الدالة العودية لحل اللغز
        SolveHanoi(n, 'A', 'C', 'B');
    }

    static void SolveHanoi(int n, char from, char to, char aux)
    {
        // الحالة الأساسية: قرص واحد فقط ننقله مباشرة
        if (n == 1)
        {
            Console.WriteLine($"Move disk 1 from {from} to {to}");
            return;
        }

        // ننقل n-1 قرصاً من العمود المصدر إلى العمود المساعد
        SolveHanoi(n - 1, from, aux, to);

        // ننقل القرص الأكبر إلى العمود الهدف
        Console.WriteLine($"Move disk {n} from {from} to {to}");

        // ننقل n-1 قرصاً من العمود المساعد إلى العمود الهدف
        SolveHanoi(n - 1, aux, to, from);
    }
}

